namespace Bitwarden.Server.Sdk.RestrictedDependencies.Tests;

/// <summary>
/// The reader is hand-rolled because an analyzer cannot carry System.Text.Json, so its own failure
/// paths are covered here rather than only through the baseline documents that use it.
/// </summary>
public class BudgetJsonSerializerTests
{
    /// <summary>
    /// A baseline's root is always an object. Whitespace anywhere around a token must parse, so a
    /// CRLF checkout reads the same as an LF one.
    /// </summary>
    [Theory]
    [InlineData("{}", 0)]
    [InlineData("  \t\r\n { \"a\" : 1 }  \r\n ", 1)]
    public void Parse_AcceptsAnObjectRootWithWhitespaceAnywhere(string json, int members) =>
        Assert.Equal(members, Assert.IsType<Dictionary<string, object?>>(BudgetJsonSerializer.Parse(json)).Count);

    [Theory]
    [InlineData("")] // empty input
    [InlineData("{")] // unclosed object
    [InlineData("[")] // unclosed array
    [InlineData("{ \"a\": 1 ")] // unclosed object after a member
    [InlineData("[ 1, ")] // unclosed array after an element
    [InlineData("{ \"a\" 1 }")] // missing colon
    [InlineData("{ a: 1 }")] // unquoted key
    [InlineData("\"unterminated")] // unterminated string
    [InlineData("\"bad \\q escape\"")] // unknown escape
    [InlineData("\"trailing backslash \\")] // unterminated escape
    [InlineData("\"\\u12\"")] // truncated unicode escape
    [InlineData("{} trailing")] // trailing content
    [InlineData("nul")] // truncated literal
    [InlineData("-")] // sign with no digits
    [InlineData("1.5")] // a decimal, which the baseline schema has no use for
    [InlineData("99999999999999999999")] // an integer too large for long
    [InlineData("@")] // a character that starts no token
    public void Parse_RejectsMalformedInput(string json) =>
        Assert.Throws<FormatException>(() => BudgetJsonSerializer.Parse(json));

    [Fact]
    public void Parse_RejectsDeeplyNestedInput_RatherThanOverflowingTheStack()
    {
        // A StackOverflowException cannot be caught, so unbounded nesting would take down the
        // compiler hosting the analyzer instead of being reported as a malformed baseline.
        var deep = new string('[', 5_000) + new string(']', 5_000);

        var error = Assert.Throws<FormatException>(() => BudgetJsonSerializer.Parse(deep));

        Assert.Contains("levels deep", error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Parse_AcceptsTheNestingTheBaselineFormatActuallyUses()
    {
        // document -> sites array -> site object is three levels; the limit must clear it easily.
        BudgetJsonSerializer.Parse("{ \"sites\": [ { \"kind\": \"member\", \"nested\": [ [ { \"a\": 1 } ] ] } ] }");
    }

    [Fact]
    public void Parse_ReadsEveryValueTypeTheGrammarAllows()
    {
        var value = Assert.IsType<Dictionary<string, object?>>(
            BudgetJsonSerializer.Parse("{ \"n\": null, \"t\": true, \"f\": false, \"zero\": 0, \"negative\": -12, \"positive\": 42, \"empty\": \"\" }"));

        Assert.Null(value["n"]);
        Assert.True(Assert.IsType<bool>(value["t"]));
        Assert.False(Assert.IsType<bool>(value["f"]));
        Assert.Equal(0L, Assert.IsType<long>(value["zero"]));
        Assert.Equal(-12L, Assert.IsType<long>(value["negative"]));
        Assert.Equal(42L, Assert.IsType<long>(value["positive"]));
        Assert.Equal(string.Empty, value["empty"]);
    }

    [Fact]
    public void Parse_ReadsEscapesAndUnicode()
    {
        var value = Assert.IsType<Dictionary<string, object?>>(
            BudgetJsonSerializer.Parse("{ \"k\": \"a\\\"b\\\\c\\/d\\be\\ff\\ng\\rh\\ti\\u0041\" }"));

        Assert.Equal("a\"b\\c/d\be\ff\ng\rh\tiA", value["k"]);
    }

    [Fact]
    public void WriteString_EscapesControlCharactersAndQuotes()
    {
        var builder = new System.Text.StringBuilder();

        BudgetJsonSerializer.WriteString(builder, "a\"b\\c\nd\re\tf\u0001");

        Assert.Equal("\"a\\\"b\\\\c\\nd\\re\\tf\\u0001\"", builder.ToString());
    }

    [Fact]
    public void WriteString_RoundTripsThroughParse()
    {
        const string original = "M:Bit.Api.X.Run(System.String[],\"quoted\",\\slash\\)";
        var builder = new System.Text.StringBuilder();
        BudgetJsonSerializer.WriteString(builder, original);

        var parsed = Assert.IsType<Dictionary<string, object?>>(BudgetJsonSerializer.Parse($"{{ \"k\": {builder} }}"));

        Assert.Equal(original, parsed["k"]);
    }
}

namespace Bitwarden.Server.Sdk.RestrictedDependencies.Tests;

/// <summary>
/// <c>ToToken</c> and <c>TryParse</c> are two independent hand-written switches over the same
/// enum, and <c>ToToken</c>'s <c>_ =&gt; throw</c> arm suppresses the exhaustiveness warning that
/// would otherwise catch a new member. That throw would reach Roslyn as AD0001 rather than a
/// diagnostic, because every caller catches only <see cref="FormatException"/>.
/// </summary>
public class DependencyUsageTypeExtensionsTests
{
    [Fact]
    public void EveryKind_RoundTripsThroughItsToken()
    {
        Assert.All(Enum.GetValues<DependencyUsageType>(), kind =>
        {
            Assert.True(DependencyUsageTypeExtensions.TryParse(kind.ToToken(), out var parsed), $"'{kind}' has no token.");
            Assert.Equal(kind, parsed);
        });
    }

    [Theory]
    [InlineData("")]
    [InlineData("bogus")]
    [InlineData("Member")]
    [InlineData("member ")]
    public void TryParse_UnknownToken_ReturnsFalseRatherThanThrowing(string token)
    {
        Assert.False(DependencyUsageTypeExtensions.TryParse(token, out _));
    }
}

using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;
using Microsoft.CodeAnalysis.Text;
using Microsoft.Extensions.DependencyInjection;

namespace Bitwarden.Server.Sdk.RestrictedDependencies.Analyzers.Tests;

/// <summary>
/// Drives the analyzer the way a repository's baseline tool does: a seed list of restricted types
/// through analyzer config, BW0017 through the compilation options, and no test harness in
/// between, because that wiring is what the observation tests check.
/// </summary>
internal static class ToolHost
{
    /// <summary>
    /// <paramref name="seedTypes"/> and <paramref name="baselineJson"/> exist because this host is
    /// the only one that can express a seed with the observation channel left off: the analyzer
    /// test harness enables every supported diagnostic, BW0017 included, so a seed there always
    /// lands in real observe mode.
    /// </summary>
    public static async Task<ImmutableArray<Diagnostic>> RunAsync(
        bool observe,
        bool enableObservations,
        string consumer = SampleProjectFixture.Consumer,
        string? seedTypes = null,
        string? baselineJson = null)
    {
        var cancellationToken = [REDACTED];
        var references = await ReferenceAssemblies.Net.Net100.ResolveAsync(LanguageNames.CSharp, cancellationToken);

        var options = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);
        if (enableObservations)
        {
            options = options.WithSpecificDiagnosticOptions(
                ImmutableDictionary<string, ReportDiagnostic>.Empty
                    .Add(DiagnosticDescriptors.Observation.Id, ReportDiagnostic.Info));
        }

        var compilation = CSharpCompilation.Create(
            SampleProjectFixture.Project,
            [
                Parse("/repo/src/Core/RestrictedDependencyAttributes.g.cs", AttributeConstants.Text),
                Parse(SampleProjectFixture.ServicePath, SampleProjectFixture.Service),
                Parse(SampleProjectFixture.ConsumerPath, consumer),
            ],
            references.Add(MetadataReference.CreateFromFile(typeof(IServiceCollection).Assembly.Location)),
            options);

        // A precondition of this host, not something a test asserts: analyzer results only mean
        // anything if the sample project compiled, so say so here rather than letting a caller's
        // expectations fail for an unrelated reason.
        var errors = compilation.GetDiagnostics(cancellationToken)
            .Where(d => d.Severity == DiagnosticSeverity.Error)
            .ToList();
        if (errors.Count != 0)
        {
            throw new InvalidOperationException(
                $"{nameof(ToolHost)} requires the sample project to compile, but it reported "
                + $"{errors.Count} error(s): {string.Join("; ", errors)}");
        }

        var additionalFiles = baselineJson is null
            ? ImmutableArray<AdditionalText>.Empty
            : ImmutableArray.Create<AdditionalText>(new BaselineFile($"/repo/baselines/{SampleProjectFixture.Type}.json", baselineJson));

        var analyzerOptions = new AnalyzerOptions(additionalFiles, Options(observe, seedTypes, markBaselines: baselineJson is not null));
        var withAnalyzers = new CompilationWithAnalyzers(
            compilation,
            [new RestrictedDependencyAnalyzer()],
            new CompilationWithAnalyzersOptions(analyzerOptions, onAnalyzerException: null, concurrentAnalysis: true, logAnalyzerExecutionTime: false));

        var diagnostics = await withAnalyzers.GetAnalyzerDiagnosticsAsync(cancellationToken);

        // Roslyn turns an analyzer exception into an AD0001 row rather than throwing, which would
        // let a caller asserting a diagnostic's absence pass on a crash.
        var crashes = diagnostics.Where(d => d.Id == "AD0001").ToList();
        if (crashes.Count != 0)
        {
            throw new InvalidOperationException(
                $"{nameof(ToolHost)} requires the analyzer to run to completion, but it threw: {string.Join("; ", crashes)}");
        }

        return diagnostics;
    }

    /// <summary>
    /// The property bags of every BW0017 diagnostic carrying the given row shape.
    /// </summary>
    public static List<ImmutableDictionary<string, string?>> Rows(ImmutableArray<Diagnostic> diagnostics, string row) =>
    [
        .. diagnostics
            .Where(d => d.Id == DiagnosticDescriptors.Observation.Id
                && d.Properties.TryGetValue(ObservationConstants.Row, out var value) && value == row)
            .Select(d => d.Properties),
    ];

    /// <summary>
    /// The one usage row of the given access shape; fails when there is none or more than one.
    /// </summary>
    public static ImmutableDictionary<string, string?> OfKind(
        IEnumerable<ImmutableDictionary<string, string?>> usages,
        string kind) =>
        Assert.Single(usages, u => u[ObservationConstants.UsageKind] == kind);

    private static SyntaxTree Parse(string path, string text) =>
        CSharpSyntaxTree.ParseText(SourceText.From(text), path: path);

    /// <summary>
    /// The global analyzer config a baseline tool generates. Naming a seed type is one of the two
    /// halves of observe mode; the other is BW0017, which only the compilation options carry.
    /// </summary>
    private static TestAnalyzerConfigOptionsProvider Options(bool observe, string? seedTypes, bool markBaselines)
    {
        var global = new Dictionary<string, string>
        {
            [AnalyzerConfigConstants.Analysis] = "true",
            [AnalyzerConfigConstants.RepositoryRoot] = SampleProjectFixture.RepoRoot,
        };

        if (observe)
        {
            global[AnalyzerConfigConstants.SeedTypes] = seedTypes ?? SampleProjectFixture.Type;
        }

        var fileOptions = markBaselines
            ? new Dictionary<string, string> { [AnalyzerConfigConstants.BaselineMetadata] = "true" }
            : null;

        return new TestAnalyzerConfigOptionsProvider(global, fileOptions);
    }

    /// <summary>
